// Parser PURO del comando de reprogramacion. No lee ni escribe estado: todo lo
// que el paso siguiente necesita viaja en el callback_data del boton que lo
// disparo (design D2). Un flujo stateless sobrevive a un reinicio de n8n y a dos
// pacientes reprogramando en paralelo, y no deja estado colgado cuando alguien
// abandona a mitad de camino.
//
// Vocabulario (design D3). Las claves son cortas porque Telegram corta el
// callback_data en 64 BYTES y rechaza el boton entero, en silencio:
//
//   cmd:reprogramar                              -> listar los turnos del chat
//   cmd:reprogramar:t:<id>                       -> ofrecer fechas
//   cmd:reprogramar:t:<id>:f:<fecha>             -> ofrecer horarios
//   cmd:reprogramar:t:<id>:f:<fecha>:h:<hora>    -> pedir confirmacion
//   cmd:reprogramar:ok:<id>:<fecha>:<hora>       -> ejecutar
//
// Y la forma LARGA, que NO es retrocompatibilidad opcional (design D3b): el
// boton "Reprogramar" del recordatorio lo arma el BACKEND en
// telegram_service.format_recordatorio_keyboard y emite exactamente
// 'cmd:reprogramar:turno_id:<id>'. Por ahi entra la mayoria de las
// reprogramaciones; ignorarla dejaria ese boton muerto sin que nada falle.
//
// NO existe ninguna entrada tipeada. Pedirle al paciente el ID de su turno es
// pedirle un dato que no tiene, y el parser que lo aceptaba produjo un bucle: el
// bot indicaba '/reprogramar <ID>' con espacio y solo aceptaba dos puntos.
const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const text = String(input.text || '');

let accion = 'listar';
let turnoId = '';
let fecha = '';
let hora = '';

const mEjecutar = text.match(/^cmd:reprogramar:ok:(\d+):(\d{4}-\d{2}-\d{2}):(.+)$/);
const mConfirmar = text.match(/^cmd:reprogramar:t:(\d+):f:(\d{4}-\d{2}-\d{2}):h:(.+)$/);
const mHorarios = text.match(/^cmd:reprogramar:t:(\d+):f:(\d{4}-\d{2}-\d{2})$/);
const mFechas = text.match(/^cmd:reprogramar:t:(\d+)$/);
const mLegacy = text.match(/^cmd:reprogramar:turno_id:(\d+)$/);

if (mEjecutar) {
  accion = 'ejecutar';
  turnoId = mEjecutar[1];
  fecha = mEjecutar[2];
  hora = mEjecutar[3];
} else if (mConfirmar) {
  accion = 'confirmar';
  turnoId = mConfirmar[1];
  fecha = mConfirmar[2];
  hora = mConfirmar[3];
} else if (mHorarios) {
  accion = 'horarios';
  turnoId = mHorarios[1];
  fecha = mHorarios[2];
} else if (mFechas) {
  accion = 'fechas';
  turnoId = mFechas[1];
} else if (mLegacy) {
  accion = 'fechas';
  turnoId = mLegacy[1];
}

// Degradacion: un callback incompleto o malformado no puede seguir de largo con
// un dato vacio -- asi nacio el PUT con nueva_hora_inicio "none". Sin los datos
// que el paso necesita, se muestra la lista y el paciente vuelve a elegir.
if (accion !== 'listar' && !turnoId) accion = 'listar';
if ((accion === 'horarios' || accion === 'confirmar' || accion === 'ejecutar') && !fecha) accion = 'listar';
if ((accion === 'confirmar' || accion === 'ejecutar') && !hora) accion = 'listar';

return [{
  json: {
    chat_id: chatId,
    accion: accion,
    turno_id: turnoId,
    fecha: fecha,
    hora: hora
  }
}];

let decidido = {};
try {
  decidido = $('Code - Decidir Paso').first().json || {};
} catch (e) {}
const chatId = decidido.chat_id;

const DIAS = ['Dom', 'Lun', 'Mar', 'Mie', 'Jue', 'Vie', 'Sab'];

// Se arma con Date.UTC y se lee con getUTCDay() para que el dia de la semana no
// dependa del timezone del server. Los datos ya vienen en hora local del
// profesional: esto NO convierte horarios, solo les da forma legible.
function legible(fecha, horaInicio) {
  const p = String(fecha).split('-').map(Number);
  const dia = DIAS[new Date(Date.UTC(p[0], p[1] - 1, p[2])).getUTCDay()];
  return dia + ' ' + String(p[2]).padStart(2, '0') + '/' + String(p[1]).padStart(2, '0') +
    ' · ' + String(horaInicio || '').slice(0, 5);
}

const http = ($input.all()[0] && $input.all()[0].json) || {};
const status = http.statusCode;
const ok = typeof status === 'number' && status >= 200 && status < 300;
let turnos = http.body;
if (!Array.isArray(turnos)) turnos = [];

// Con neverError un 422 tambien llega aca, con un body que no es array. Sin esta
// distincion el paciente leeria "no tenes turnos" ante un fallo del backend, que
// es indistinguible de una lista vacia legitima -- y por esa ambiguedad se dio
// por bueno un smoke test que no probaba nada.
let mensaje;
let teclado;
if (!ok) {
  mensaje = 'No pudimos consultar tus turnos ahora. Proba de nuevo en un rato.';
  teclado = [[{ text: 'Reintentar', callback_data: 'cmd:reprogramar' }]];
} else if (turnos.length === 0) {
  mensaje = 'No tenes turnos para reprogramar.';
  teclado = [[{ text: 'Reservar un turno', callback_data: 'cmd:crear' }]];
} else {
  mensaje = 'Cual turno queres reprogramar?';
  teclado = turnos.map(function (t) {
    return [{
      text: legible(t.fecha, t.hora_inicio),
      callback_data: 'cmd:reprogramar:t:' + t.id
    }];
  });
  // Todo paso ofrece una salida. Un paciente que entro por equivocacion o que
  // se retracta no tiene que quedar obligado a elegir un turno para salir: sin
  // esta fila, la unica salida de la lista es escribir un comando que nadie le
  // dijo que existe.
  teclado.push([{ text: 'Volver al menu', callback_data: 'cmd:menu' }]);
}

return [{
  json: {
    chat_id: chatId,
    cantidad: ok ? turnos.length : 0,
    mensaje: mensaje,
    inline_keyboard: teclado
  }
}];

function fmtArgentina(d) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(d);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const dd = parts.find(p => p.type === 'day').value;
  return y + '-' + m + '-' + dd;
}

function addDays(yyyy_mm_dd, n) {
  const partes = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(partes[0], partes[1] - 1, partes[2]));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return yy + '-' + mm + '-' + dd;
}

function hoyArgentina() {
  return fmtArgentina(new Date());
}

let decidido = {};
try {
  decidido = $('Code - Decidir Paso').first().json || {};
} catch (e) {}
const chatId = decidido.chat_id;
const turnoId = decidido.turno_id;

// OQ-1 resuelta: 7 dias fijos. calcular_disponibilidad devuelve lista vacia para
// un dia fuera de dias_atencion, asi que un dia sin agenda cae en la rama de
// "elegi otra fecha" y no hace falta filtrarlo antes de ofrecerlo.
//
// OQ-2: reprogramar para HOY deberia poderse, pero el backend todavia no filtra
// los slots ya pasados -- pedir disponibilidad de hoy a las 18:00 devuelve los
// de las 09:00. Por eso la ventana arranca manana. DIA_INICIO es una constante
// nombrada a proposito: el change que habilite hoy la mueve a 0 y no reescribe
// nada mas.
const DIA_INICIO = 1;
const DIAS_A_OFRECER = 7;

const hoy = hoyArgentina();
const manana = addDays(hoy, 1);

const DIAS = ['Dom', 'Lun', 'Mar', 'Mie', 'Jue', 'Vie', 'Sab'];
const MESES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];

// La etiqueta se deriva de la FECHA, no del indice del loop. Al reves --que era
// como estaba-- el primer boton decia "Hoy" y era manana.
function etiqueta(fecha) {
  if (fecha === hoy) return 'Hoy';
  if (fecha === manana) return 'Manana';
  const p = fecha.split('-').map(Number);
  const d = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
  return DIAS[d.getUTCDay()] + ' ' + p[2] + ' ' + MESES[p[1] - 1];
}

const teclado = [];
for (let i = 0; i < DIAS_A_OFRECER; i++) {
  const fecha = addDays(hoy, DIA_INICIO + i);
  teclado.push([{
    text: etiqueta(fecha) + ' (' + fecha + ')',
    callback_data: 'cmd:reprogramar:t:' + turnoId + ':f:' + fecha
  }]);
}
teclado.push([{ text: 'Volver a mis turnos', callback_data: 'cmd:reprogramar' }]);

return [{
  json: {
    chat_id: chatId,
    turno_id: turnoId,
    mensaje: 'Elegi la nueva fecha:',
    inline_keyboard: teclado
  }
}];

let decidido = {};
try {
  decidido = $('Code - Decidir Paso').first().json || {};
} catch (e) {}
const chatId = decidido.chat_id;
const turnoId = decidido.turno_id;
const fecha = decidido.fecha;

// GET /turnos/disponibles devuelve list[SlotResponse]: un array JSON PELADO. Con
// fullResponse el array queda bajo .body. La version anterior buscaba
// Array.isArray(input) o input.slots sobre el primer objeto slot -- ninguna de
// las dos da true nunca, asi que la lista salia vacia SIEMPRE y el paciente veia
// "no hay horarios" con la agenda entera libre.
const http = ($input.all()[0] && $input.all()[0].json) || {};
const status = http.statusCode;
const ok = typeof status === 'number' && status >= 200 && status < 300;
let slots = http.body;
if (!Array.isArray(slots)) slots = [];

const libres = ok ? slots.filter(function (s) { return s && s.disponible !== false; }) : [];

let mensaje;
let teclado;
if (!ok) {
  mensaje = 'No pudimos consultar los horarios de esa fecha. Proba de nuevo.';
  teclado = [[{ text: 'Elegir otra fecha', callback_data: 'cmd:reprogramar:t:' + turnoId }]];
} else if (libres.length === 0) {
  // Sin horarios se ofrece CAMBIAR DE FECHA. La version anterior emitia un boton
  // con ':slot:none', que el parser leia como un horario elegido y terminaba en
  // un PUT con nueva_hora_inicio "none". Ningun boton emite un callback_data que
  // el flujo no sepa procesar (design D7).
  mensaje = 'No quedan horarios libres para el ' + fecha + '.';
  teclado = [[{ text: 'Elegir otra fecha', callback_data: 'cmd:reprogramar:t:' + turnoId }]];
} else {
  mensaje = 'Elegi el nuevo horario para el ' + fecha + ':';
  teclado = libres.map(function (s) {
    const hasta = s.hora_fin ? (' - ' + s.hora_fin) : '';
    return [{
      text: s.hora_inicio + hasta,
      callback_data: 'cmd:reprogramar:t:' + turnoId + ':f:' + fecha + ':h:' + s.hora_inicio
    }];
  });
  teclado.push([{ text: 'Elegir otra fecha', callback_data: 'cmd:reprogramar:t:' + turnoId }]);
}

return [{
  json: {
    chat_id: chatId,
    cantidad: libres.length,
    mensaje: mensaje,
    inline_keyboard: teclado
  }
}];

let decidido = {};
try {
  decidido = $('Code - Decidir Paso').first().json || {};
} catch (e) {}
const chatId = decidido.chat_id;
const turnoId = decidido.turno_id;
const fecha = decidido.fecha;
const hora = decidido.hora;

const DIAS = ['Dom', 'Lun', 'Mar', 'Mie', 'Jue', 'Vie', 'Sab'];
function legible(f, h) {
  const p = String(f).split('-').map(Number);
  const dia = DIAS[new Date(Date.UTC(p[0], p[1] - 1, p[2])).getUTCDay()];
  return dia + ' ' + String(p[2]).padStart(2, '0') + '/' + String(p[1]).padStart(2, '0') +
    ' · ' + String(h || '').slice(0, 5);
}

// Se relee la lista para detectar turnos cancelados o vencidos entre que se
// mostro el boton y se toco. Un boton de Telegram queda vivo en el historial del
// chat indefinidamente (design D9).
const http = ($input.all()[0] && $input.all()[0].json) || {};
const status = http.statusCode;
const ok = typeof status === 'number' && status >= 200 && status < 300;
let turnos = http.body;
if (!Array.isArray(turnos)) turnos = [];

const turno = turnos.filter(function (t) { return String(t.id) === String(turnoId); })[0];
const vigente = ok && !!turno;

let mensaje;
let teclado;
if (!vigente) {
  mensaje = 'Ese turno ya no esta en tu lista. Puede que lo hayan cancelado o que ya haya pasado.';
  teclado = [[{ text: 'Ver mis turnos', callback_data: 'cmd:reprogramar' }]];
} else {
  mensaje = 'Confirmas mover tu turno?\n\nDe: ' + legible(turno.fecha, turno.hora_inicio) +
    '\nA: ' + legible(fecha, hora);
  teclado = [
    [{ text: 'Si, mover el turno', callback_data: 'cmd:reprogramar:ok:' + turnoId + ':' + fecha + ':' + hora }],
    [{ text: 'No', callback_data: 'cmd:menu' }]
  ];
}

return [{
  json: {
    chat_id: chatId,
    vigente: vigente,
    mensaje: mensaje,
    inline_keyboard: teclado
  }
}];

let decidido = {};
try {
  decidido = $('Code - Decidir Paso').first().json || {};
} catch (e) {}
const chatId = decidido.chat_id;
const turnoSolicitado = decidido.turno_id;

const http = ($input.all()[0] && $input.all()[0].json) || {};
const status = http.statusCode;
const body = http.body || {};

// El exito se DERIVA del status. Un status ausente o no reconocido es un FALLO,
// no un exito por defecto: con neverError tambien llegan aca los errores de red
// y los 5xx, y asumir exito ante lo desconocido es como el flujo terminaba
// diciendo "turno reprogramado" sobre un 422.
const ok = typeof status === 'number' && status >= 200 && status < 300;

// TurnoResponse expone 'id', no 'turno_id'. Leerlo mal producia
// "Turno #undefined reprogramado".
const turnoId = body.id || turnoSolicitado;

let mensaje;
let teclado;
if (ok) {
  mensaje = 'Listo, tu turno quedo para el ' + body.fecha + ' a las ' +
    String(body.hora_inicio || '').slice(0, 5) + '.\n\nTe vamos a recordar antes.';
  teclado = [[{ text: 'Volver al menu', callback_data: 'cmd:menu' }]];
} else if (status === 404) {
  mensaje = 'No encontramos ese turno. Puede que ya lo hayan cancelado.';
  teclado = [[{ text: 'Ver mis turnos', callback_data: 'cmd:reprogramar' }]];
} else if (status === 409) {
  mensaje = 'Ese horario ya fue tomado, o el turno no se puede mover en su estado actual.';
  teclado = [[{ text: 'Elegir otro horario', callback_data: 'cmd:reprogramar:t:' + turnoSolicitado }]];
} else {
  const detalle = body.detail ? (' (' + body.detail + ')') : '';
  mensaje = 'No pudimos mover el turno' + detalle + '. Tu turno original sigue vigente.';
  teclado = [[{ text: 'Ver mis turnos', callback_data: 'cmd:reprogramar' }]];
}

return [{
  json: {
    chat_id: chatId,
    turno_id: turnoId,
    exito: ok,
    mensaje: mensaje,
    inline_keyboard: teclado
  }
}];
